import json,re,runpy
from pathlib import Path
P=Path('/workspace/sites/olympiad-atlas')
hrecords=[];hscreen=[]
def add(y,c,q,d,t,st,why,sol=None,tags=None,notes=None,date=None):
 rec={'id':f'{c.lower()}-{y}-q{q}','country':'United Kingdom','competition':c,'year':y,'number':str(q),'statement':st,'solution':sol,'sourceUrl':f'https://bmos.ukmt.org.uk/home/{c.lower()}-{y}.pdf','solutionUrl':None,'topic':t,'tags':tags or [],'difficulty':d,'ratingReason':why,'reviewStatus':'individually-assessed','notes':notes or 'Historical paper: statement paraphrased from the official scan. Difficulty is an individual AI estimate, not an official UKMT rating.'}
 if date:rec['sittingDate']=date
 hrecords.append(rec);hscreen.append({'year':y,'competition':c,'number':str(q),'difficulty':d,'decision':'include','reason':why})
def omit(y,c,q,d,why):hscreen.append({'year':y,'competition':c,'number':str(q),'difficulty':d,'decision':'exclude','reason':why})
def save():
 m=runpy.run_path(str(P/'research/build_british.py'),run_name='__modern_data__');m['save']()
 modern=json.loads((P/'data/british.json').read_text());cov=json.loads((P/'research/british-coverage.json').read_text())
 (P/'research/british-historic-records.json').write_text(json.dumps(hrecords,ensure_ascii=False,indent=2))
 (P/'data/british.json').write_text(json.dumps(hrecords+modern,ensure_ascii=False,indent=2))
 hp=[]
 for c,y in sorted(set((s['competition'],s['year']) for s in hscreen)):
  ss=[s for s in hscreen if s['competition']==c and s['year']==y]
  hp.append({'competition':c,'archiveYear':y,'status':'fully-screened','questionCount':len(ss),'includedCount':sum(s['decision']=='include' for s in ss),'questionNumbers':[s['number'] for s in ss],'sourceUrl':f'https://bmos.ukmt.org.uk/home/{c.lower()}-{y}.pdf'})
 cov['papers']=hp+cov['papers'];cov['historicalScreening']=hscreen
 cov['counts']['historicalPapersFullyScreened']=len(hp);cov['counts']['papersFullyScreened']+=len(hp)
 cov['counts']['included']+=len(hrecords);cov['counts']['assessed']+=len(hscreen);cov['counts']['excluded']+=sum(s['decision']=='exclude' for s in hscreen);cov['counts']['withOwnWorkedSolution']+=sum(bool(r['solution']) for r in hrecords)
 cov['fullyScreenedRange']='BMO 1973–1991; all accessible FIST papers (1972, 1974–1986, 1988–1991); BMO1 and BMO2 archive seasons 1992–2026.'
 cov['gaps'][0]={'range':'Historical BMO and FIST extension','status':'all accessible official-archive papers fully screened','fullyScreenedPapers':[f"{p['competition']} {p['archiveYear']}" for p in hp],'detail':'All 19 available BMO papers from 1973–1991 and all 18 available FIST papers are complete. Printed either/or alternatives are recorded as separate assessment decisions. No FIST was held in 1987; the archive mentions a Reading Selection Test but does not link its paper.'}
 cov['yearConvention']+=' Historical BMO 1988 was sat 20 November 1987 and BMO 1989 was sat 13 December 1988. Per-record sittingDate fields retain the actual dated headers; undated 1973/1974 papers have no invented date.'
 cov['sourceAudit']={'archivePaperLinks':'Every included source URL matched against the official archive index.','sittingDates':'All included dated papers checked against their PDF headers and archive date labels; whitespace-normalised agreement. BMO 1973, BMO 1974 and FIST 1974 have only year labels.','publicSolutionRanges':['Official BMO1 videos: archive years 2006–2026','Official BMO2 written solutions: 2021 and 2022','Official BMO2 videos: 2024–2026'],'publicSolutionCoverage':'Every included record in these public ranges links the official solution resource. No other free official solution range is advertised by the archive or video index. Historical book solutions have not been copied.'}
 (P/'research/british-coverage.json').write_text(json.dumps(cov,ensure_ascii=False,indent=2))
 print('Historical',len(hrecords),'selected from',len(hscreen),'decisions;',len(hp),'papers. Total',len(hrecords)+len(modern))
# Each rating below is based on individual mathematical analysis of the scanned problem.
omit(1973,'BMO',1,8,'The requested extension from tangent circles to arbitrary conics makes the full question substantially beyond modern hard-BMO1 geometry.')
omit(1973,'BMO',2,3.5,'Partition the unit square into four smaller squares; three of the nine points lie in one, giving the area bound immediately.')
omit(1973,'BMO',3,8.5,'A geodesic crossing a hemisphere-cylinder seam requires spherical geometry and a variational argument beyond the target band.')
omit(1973,'BMO',4,7.5,'A complete numerical classification of triangular-lattice equiangular hexagon areas requires a substantial quadratic-form analysis.')
add(1973,'BMO',5,4.5,'Number theory',r'Prove that there is an infinite set of positive integers of the form $2^n-7$ such that any two members are coprime. The paper gives a Fermat-theorem construction for $2^n-3$ as a model.','The exponent must be shifted appropriately so that the new term avoids every prime already used.',r'Suppose finitely many pairwise coprime terms have been chosen, and let $p_1,\ldots,p_s$ be all their prime divisors. They are odd. Choose a positive common multiple $L$ of $p_1-1,\ldots,p_s-1$ (take $L=1$ if there are none). Fermat gives $2^{kL+3}-7\equiv8-7=1\pmod{p_i}$ for every $i$. Choose $k$ large enough that this positive term exceeds all previous ones. It is coprime to each of them and extends the set. Induction constructs an infinite set.',['Fermat','Coprimality','Infinite constructions'])
omit(1973,'BMO',6,3,'Under the intended independent-answer model, total probability gives a single linear equation for the sex ratio; degeneracies also need noting.')
omit(1974,'BMO','A1',7.5,'Determining an area-bisecting curve from mixed horizontal and vertical boundaries involves a differential-equation interpretation outside the intended elementary range.')
add(1974,'BMO','B2',6.5,'Combinatorics',r'Take the 15 dominoes corresponding to unordered pairs from $\{1,2,3,4,5\}$, allowing doubles. Partition them into three unordered groups of five, each of which can be arranged as a closed chain $(a,b),(b,c),(c,d),(d,e),(e,a)$. How many partitions are possible?','Each group is an Eulerian five-edge graph with loops permitted; classifying the possible components and avoiding overcounted chains is substantial.',None,['Graph decompositions','Eulerian graphs','Counting'])
omit(1974,'BMO','A3',3.5,'Euler gives V-E+F=2 while six edges per face and at least three edges per vertex would force V-E+F at most zero.')
add(1974,'BMO','A4',4,'Algebra',r'A $16\times16$ matrix $M$ has entries $1$ on its main diagonal and throughout its bottom row; all other entries are $1/2$. Find $M^{-1}$.','The dense-looking matrix has a simple row-sum structure, so solving Mx=y reveals the inverse directly.',r'Let $Mx=y$ and $S=\sum_{i=1}^{16}x_i$. The last row gives $S=y_{16}$. For $i\le15$, $y_i=(S+x_i)/2$, hence $x_i=2y_i-y_{16}$. Therefore $x_{16}=S-\sum_{i=1}^{15}x_i=16y_{16}-2\sum_{i=1}^{15}y_i$. Thus the upper-left $15\times15$ block of $M^{-1}$ is $2I$, its first fifteen entries in the last column are $-1$, its first fifteen entries in the last row are $-2$, and its bottom-right entry is $16$.',['Matrices','Linear equations'],'Historical algebra problem using matrix notation; statement paraphrased from the official scan. Individual AI difficulty estimate.')
add(1974,'BMO','A5',6,'Combinatorics',r'A standard 52-card deck is dealt to four labelled players, thirteen cards each. Find the probability that exactly one player receives a complete suit. An answer using factorials is acceptable.','Inclusion-exclusion must count compatible player-suit assignments and isolate exactly one event, rather than at least one.',None,['Inclusion-exclusion','Probability','Counting'])
add(1974,'BMO','B6',4.5,'Geometry','Let $X,Y$ be the perpendicular feet from a point $P$ to the lines $CA,CB$ of triangle $ABC$, with $PX=PY$. The line through $P$ perpendicular to $AB$ meets $XY$ at $Z$. Prove that $CZ$ bisects $AB$.','The equal distances put P on an angle bisector at C. Coordinates along that bisector make XY a line of constant first coordinate; the perpendicular condition then identifies CZ as the median. The construction must be followed carefully, but the resulting calculation is short.','Choose coordinates $C=(0,0)$ and $P=(p,0)$. Since $P$ is equidistant from the two side lines, write $A=(a,ta)$ and $B=(b,-tb)$, allowing signed $a,b$ to cover both angle bisectors. The perpendicular feet have first coordinate $p/(1+t^2)$, so $Z=(p/(1+t^2),z)$.\n\nThe direction of $AB$ is $(b-a,-t(a+b))$. Since $PZ\\perp AB$,\n$$(b-a)\\left(\\frac{p}{1+t^2}-p\\right)-t(a+b)z=0,$$\nwhence\n$$Z=\\frac{p}{(1+t^2)(a+b)}\\,(a+b,t(a-b)).$$\nThe midpoint of $AB$ is $((a+b)/2,t(a-b)/2)$, proving the required collinearity with $C$. The nondegeneracy implicit in the defined intersection $Z$ rules out the zero denominators.',['Coordinates & vectors', 'Triangle geometry', 'Concurrency & collinearity'])
add(1974,'BMO','B7',7,'Algebra',r'The roots of $x^3=bx+c$ are $\alpha,\beta,\gamma$, where $b,c$ are nonzero real numbers. Find $p,q,r$ in terms of $b,c$ such that $\beta=p\alpha^2+q\alpha+r$, $\gamma=p\beta^2+q\beta+r$, and $\alpha=p\gamma^2+q\gamma+r$. State a condition ensuring $p,q,r$ are real.','Quadratic interpolation around a cyclic permutation of cubic roots introduces the discriminant and must handle dependence on the root ordering.',None,['Cubic equations','Interpolation','Discriminants'])
add(1974,'BMO','A8',6.5,'Number theory',r'For an odd prime $p$, write $P(x)=\prod_{i=1}^{p-1}(x+i)=\sum_{j=0}^{p-1}a_jx^j$. Use the identity $(x+p)P(x)=(x+1)P(x+1)$ to obtain a descending coefficient recurrence, and prove $p\mid a_j$ for $1\le j\le p-2$ and $p\mid a_0+1$. Deduce Wilson\'s theorem and Fermat\'s little theorem.','A coefficient comparison must be organised into induction modulo p; the familiar theorems are conclusions, so cannot be assumed.',None,['Polynomial coefficients','Congruences','Wilson','Fermat'],'The original scaffold lists several terms of the coefficient recurrence explicitly; this paraphrase retains the same recurrence task and all conclusions.')
add(1975,'BMO',1,4.5,'Algebra',r'Find every positive integer $x$ such that $\sum_{k=1}^{x^3-1}\lfloor\sqrt[3]{k}\rfloor=400$, proving completeness.','Grouping terms between consecutive cubes gives a weighted polynomial sum; monotonicity then certifies the only solution.',None,['Floor functions','Sums of powers'],date='1975-03-24')
omit(1975,'BMO',2,3,'Any prime factor of a common product difference cannot be among the initial primes, since those primes divide exactly one product.')
add(1975,'BMO',3,4,'Geometry',r'Seven points lie in the closed unit disc, with every pair at distance at least $1$. Prove one of the points is the centre of the disc.','Six angular sectors give the bound, but equality on sector boundaries requires a careful angular-gap argument.',r'Assume no point is the centre and order the seven polar angles. Some consecutive angular gap is at most $2\pi/7<\pi/3$. If the corresponding radii are $r,s\in(0,1]$, their squared distance is $r^2+s^2-2rs\cos\theta<r^2+s^2-rs\le1$. The last inequality holds because, for fixed $s$, the convex quadratic in $r$ is at most the greater of its endpoint values $s^2$ and $1+s^2-s$, both at most 1. This contradicts the assumed separation.',['Pigeonhole principle','Packing','Cosine rule'],date='1975-03-24')
add(1975,'BMO',4,5.5,'Geometry',r'Parallel lines through vertices $A,B,C$ of a triangle meet the opposite side lines at $D,E,F$. Points $P,Q,R$ divide $AD,BE,CF$ in the same ratio $k:1$, respectively. If $P,Q,R$ are collinear, find $k$.','An affine coordinate calculation or Menelaus argument must accommodate intersections on extended sides and identify the universal ratio.',None,['Affine geometry','Menelaus','Ratios'],date='1975-03-24')
add(1975,'BMO',5,5.5,'Algebra',r'For $m\ge1$, let $f_m(\theta)=\sum_{j=0}^{2m}\binom{2m}{j}\cos(j\theta)=(2\cos(\theta/2))^{2m}\cos(m\theta)$, and let $g_m(\theta)=\sum_{j=0}^{m}\binom{2m}{2j}\cos(2j\theta)$. For real $\alpha$ with $\alpha/\pi$ irrational, determine when $\lim_{m\to\infty}g_m(\alpha)/f_m(\alpha)=1/2$.','The even-term filter uses a shifted angle; the resulting ratio simplifies to a geometric sequence despite the oscillating cosine factor.',r'Filtering the even terms gives $g_m(\alpha)=(f_m(\alpha)+f_m(\alpha+\pi))/2$. The supplied identity shows $f_m(\alpha+\pi)/f_m(\alpha)=(-1)^m\tan^{2m}(\alpha/2)$. The irrationality condition ensures the denominators do not vanish and excludes $|\tan(\alpha/2)|=1$. Therefore the required limit holds exactly when $|\tan(\alpha/2)|<1$, equivalently $\cos\alpha>0$.',['Binomial identities','Trigonometry','Limits'],date='1975-03-24')
add(1975,'BMO',6,5.5,'Algebra',r'For an integer $n>1$ and real numbers $x>y>1$, prove $\frac{x^{n+1}-1}{x(x^{n-1}-1)}>\frac{y^{n+1}-1}{y(y^{n-1}-1)}$.','The rational expression must be shown increasing uniformly in n; a direct derivative has a non-obvious numerator requiring factorisation or an inequality.',None,['Monotonicity','Inequalities','Powers'],date='1975-03-24')
omit(1975,'BMO',7,2.5,'Cauchy applied to the n+1 successive differences immediately forces equality and the arithmetic progression.')
add(1975,'BMO',8,7,'Geometry',r'A right circular conical wine glass is initially half full and is tilted slowly so water spills from one rim point $P$. What fraction of the cone remains filled when the horizontal water surface bisects the generator farthest from $P$?','The tilted section is an ellipse; computing the remaining conical volume requires relating its geometry to the two intercepted generators.',None,['Cones','Volumes','Conic sections'],date='1975-03-24')
add(1976,'BMO',1,6,'Geometry',r'Find the shortest straight segment bisecting the area of an arbitrary triangle, expressing its length in terms of the triangle area $\Delta$ and one angle. Prove a shorter, non-straight curve can also bisect its area.','Optimising cuts at each vertex identifies the smallest-angle construction; the curved improvement adds a separate feasibility and length comparison.',None,['Area','Optimisation','Circular arcs'],date='1976-03-24')
omit(1976,'BMO',2,2.5,'This is the direct three-variable Nesbitt inequality, obtainable immediately by Cauchy.')
add(1976,'BMO',3,5,'Combinatorics',r'Each of 50 subsets $S_1,\ldots,S_{50}$ of a finite set $E$ contains more than half the elements of $E$. Prove that a set of at most five elements of $E$ intersects every $S_i$.','A greedy incidence count must exploit the strict half bound at every step; a naive probabilistic union bound would give six points.',r'For any remaining collection of $k$ sets, the total incidences exceed $k|E|/2$, so some element belongs to more than $k/2$ of them. Select that element and discard the sets it hits. The possible remaining counts successively fall from $50$ to at most $24,11,5,2,0$. Thus five selections suffice; any repeated selection can be removed, leaving a set of at most five elements.',['Double counting','Greedy algorithms','Hitting sets'],date='1976-03-24')
add(1976,'BMO',4,4.5,'Number theory',r'Prove $19\cdot8^n+17$ is composite for every nonnegative integer $n$.','Different small prime divisors cover three residue classes of the exponent; no single modulus handles every n.',r'If $n$ is even, the expression is divisible by $3$, since $8\equiv-1\pmod3$. If $n\equiv1\pmod4$, it is divisible by $13$, because $8^4\equiv1\pmod{13}$ and $19\cdot8+17=169$. If $n\equiv3\pmod4$, it is divisible by $5$, since $8^n\equiv2\pmod5$. In every case the expression exceeds the indicated divisor, including $n=0$, where it is $36$.',['Covering congruences','Compositeness'],date='1976-03-24')
add(1976,'BMO',5,6,'Algebra',r'For real $\alpha,\beta$ and positive integers $r\le n$ with $r$ odd, prove $\sum_{t=0}^{(r-1)/2}\binom n{r-t}\binom nt(\alpha\beta)^t(\alpha^{r-2t}+\beta^{r-2t})=\sum_{t=0}^{(r-1)/2}\binom n{r-t}\binom{r-t}t(\alpha\beta)^t(\alpha+\beta)^{r-2t}$.','The complicated sums are coefficients of the same generating polynomial, expanded either as two binomials or one trinomial.',r'Compare the coefficient of $x^r$ in $(1+\alpha x)^n(1+\beta x)^n=(1+(\alpha+\beta)x+\alpha\beta x^2)^n$. On the left, pair the terms whose exponents are $(t,r-t)$ and $(r-t,t)$; no central unpaired term occurs because $r$ is odd. This gives the left sum. On the right, choose $r-t$ nonconstant factors and then $t$ of these to contribute the quadratic term; the others contribute the linear term. This gives the right sum.',['Generating functions','Coefficient extraction'],date='1976-03-24')
omit(1976,'BMO',6,8.5,'A shortest path across a cone-sphere seam needs spherical trigonometry and unfolding, substantially beyond the target elementary geometry.')
# Restore all reviewed historical difficulties, preserving source holds.
restoration_path=P/'research/british-restored-records.json'
if restoration_path.exists():
 restored={r['id']:r for r in json.loads(restoration_path.read_text()) if r['competition'] in ('BMO','FIST')}
 merged={r['id']:r for r in hrecords};merged.update(restored);hrecords[:]=merged.values()
 for decision in hscreen:
  ident=f"{decision['competition'].lower()}-{decision['year']}-q{decision['number']}"
  if ident in restored:decision.update(decision='include',difficulty=restored[ident]['difficulty'],reason=restored[ident]['ratingReason'])
if __name__=='__main__':save()
# Remaining pages of the unusually long 1973 and 1974 papers.
add(1973,'BMO',7,5,'Algebra',r'A population survival table is modelled on $60\le x\le100$ by $y(x)=Ax(100-x)+B/(x-40)^2$, with $y(60)=4820$ and $y(80)=3205$. Nobody survives beyond 100. Estimate the remaining life expectancy of a person aged 70, to one decimal place.','Determining the constants is straightforward; interpreting conditional life expectancy as an integral of the survival curve is the essential modelling step.',None,['Calculus','Probability','Modelling'],'Historical applied-mathematics problem requiring integration; paraphrased from the official scan. Individual AI difficulty estimate.')
add(1973,'BMO',8,6,'Algebra',r'Associate $M=\begin{pmatrix}a&b\\c&d\end{pmatrix}$, with $\det M\ne0$, to the fractional linear map $T(z)=(az+b)/(cz+d)$. (i) Show that matrix multiplication corresponds to composition of these maps. (ii) Find conditions on $a,b,c,d$ for $T^4$ to be the identity but $T^2$ not the identity.','Scalar multiples represent the same map, so finite order is a projective matrix condition rather than simply M to the fourth equal to I.',None,['Matrices','Fractional linear transformations','Finite order'])
omit(1973,'BMO',9,4.5,'The printed concurrency claim omits nondegeneracy hypotheses: equal scale parameters can give parallel lines with no finite concurrence. Excluded as under-specified rather than published with a silent repair.')
add(1973,'BMO',10,4.5,'Combinatorics',r'Design a finite algorithm, with a detailed flow chart, that prints every positive integer at most 100 of the form $a^2-b^2-c^2$, where $a,b,c$ are positive integers and $a\ge b+c$. Repetitions and non-increasing output order are allowed.','Completeness requires finite search bounds for three apparently unbounded variables; the inequality gives a sharp product bound.',r'Since $a\ge b+c$, $a^2-b^2-c^2\ge2bc$. Any requested output therefore has $bc\le50$. Loop over $b=1,\ldots,50$, then $c=1,\ldots,\lfloor50/b\rfloor$. For each pair loop over integers $a$ from $b+c$ to $\lfloor\sqrt{100+b^2+c^2}\rfloor$, and print $a^2-b^2-c^2$. These bounds are finite, each output is positive and at most 100, and the preceding inequalities show every eligible triple is visited. A flow chart consists of these three nested loops and the print step.',['Algorithms','Bounds','Enumeration'])
omit(1973,'BMO',11,9,'Coupled rigid-cylinder rolling dynamics and a nonlinear differential equation require advanced mechanics well beyond the target olympiad prerequisites.')
omit(1974,'BMO','B9',7.5,'The unstable falling-rod model requires rotational dynamics and an improper integral; its infinite-time interpretation is outside modern elementary olympiad scope.')
omit(1974,'BMO','B10',8,'Gravitational attraction of a spherical-shell-truncated cone requires spatial integration and mechanics beyond the target range.')
omit(1977,'BMO',1,3.5,'Nonnegativity gives f(2)=f(5)=0; any remaining prime can be multiplied to end in 3, forcing its value to zero.')
add(1977,'BMO',2,5,'Geometry',r'The sides $BC,CA,AB$ of a triangle touch its incircle at $X,Y,Z$. Prove that the incentre lies on the line joining the midpoints of $BC$ and $AX$.','The tangent-length relations must be combined with a midpoint construction; this is a degenerate tangential-quadrilateral Newton-line configuration.',None,['Incentre','Midpoints','Tangency'],date='1977-03-17')
add(1977,'BMO',3,4.5,'Algebra',r'(i) For nonnegative $x,y,z$, prove $x(x-y)(x-z)+y(y-z)(y-x)+z(z-x)(z-y)\ge0$. (ii) Deduce, for arbitrary real $a,b,c$, that $a^6+b^6+c^6+3a^2b^2c^2\ge2(b^3c^3+c^3a^3+a^3b^3)$.','The first part is Schur, while the second needs a square substitution and a further pairwise inequality that remains valid for negative inputs.',None,['Schur inequality','Substitution','Sum of squares'],date='1977-03-17')
add(1977,'BMO',4,5,'Algebra',r'Let $u,v,w$ be the roots of $x^3+qx+r=0$, where $r\ne0$. Express the roots of $r^2x^3+q^3x+q^3=0$ in terms of $u,v,w$. If all three original roots are real, prove the new cubic has no root in $(-1,3)$.','The scaling of roots is hidden by the coefficients; Vieta then converts each transformed root into a ratio allowing a sharp real bound.',r'The new roots are $qu/r,qv/r,qw/r$, by direct substitution. If all original roots are real, Vieta gives $u+v+w=0$, $q=uv+vw+wu$ and $r=-uvw$. Consequently $qu/r=u^2/(vw)-1$. If $vw<0$, this is less than $-1$. If $vw>0$, then $u^2=(v+w)^2\ge4vw$, so it is at least $3$. The same applies to the other two roots.',['Vieta','Cubic equations','Inequalities'],date='1977-03-17')
add(1977,'BMO',5,5.5,'Geometry',r'Five spheres of radius $a$ have centres at the vertices of a regular pentagon of side $2a$. Two further spheres, also of radius $a$, each touch all five externally. Determine, with exact proof, whether the two further spheres intersect.','Symmetry locates the two centres, but deciding intersection needs an exact pentagon circumradius comparison rather than numerical trigonometry.',None,['Spheres','Regular pentagons','Trigonometry'],date='1977-03-17')
add(1977,'BMO',6,5,'Combinatorics',r'For which integers $n>1$ can $26(x+x^2+\cdots+x^n)$ be a sum of polynomials whose coefficient lists are permutations of $1,2,\ldots,n$? Repeated summand polynomials are allowed.','Comparing total coefficients restricts the number of summands; the remaining cases need balanced permutation constructions.',r'If there are $k$ summands, total coefficients give $kn(n+1)/2=26n$, hence $k(n+1)=52$. Also $n\le26$, since every summand contains a coefficient $n$. Thus $n$ can only be $3,12,25$. For $n=25$, add a permutation and its reverse to make each coefficient 26. For $n=12$, use two copies of a permutation-reverse pair, each pair summing to 13. For $n=3$, use five permutation-reverse pairs, contributing 20 at every position, and the three cyclic permutations of $(1,2,3)$, contributing 6. All three values work.',['Permutations','Coefficient sums','Constructions'],date='1977-03-17')
add(1978,'BMO',1,4,'Geometry',r'Find the point $P$ inside a triangle $ABC$ maximising the product of its perpendicular distances to the three side lines.','The three subtriangle areas provide the weighted linear constraint needed for AM–GM, identifying the centroid rather than the incentre.',r'Let the opposite side lengths be $a,b,c$, the distances $x,y,z$, and the area $\Delta$. Then $ax+by+cz=2\Delta$. AM–GM gives $abcxyz\le(2\Delta/3)^3$, with equality exactly when $ax=by=cz$. Those quantities are twice the three subtriangle areas, so equality means those areas are equal, which uniquely identifies the centroid.',['Area','AM-GM','Centroid'],date='1978-03-21')
add(1978,'BMO',2,4,'Number theory',r'Prove no proper fraction $m/n$ with positive denominator $n\le100$ has a decimal expansion containing the consecutive digit block 167.','A block anywhere in the expansion can be shifted to the decimal point; its narrow interval lies too close to one sixth for a small denominator.',r'If the block occurs, shifting the decimal point gives a fractional part $r/n$ with $167/1000\le r/n<168/1000$. In particular $r/n>1/6$, so the positive integer $6r-n$ is at least 1. Hence $r/n-1/6\ge1/(6n)\ge1/600$. This gives $r/n\ge101/600>168/1000$, a contradiction.',['Decimal expansions','Rational approximation'],date='1978-03-21')
add(1978,'BMO',3,6.5,'Number theory',r'Prove there is exactly one integer sequence $(u_n)$ with $u_1=1<u_2$ and $u_n^3+1=u_{n-1}u_{n+1}$ for every $n>1$.','Early divisibility forces the second term, but existence requires propagating integrality through a nonlinear recurrence.',None,['Recurrences','Divisibility','Coprimality'],date='1978-03-21')
add(1978,'BMO',4,5.5,'Geometry',r'Prove that the four altitudes of a tetrahedron are concurrent if and only if every edge is perpendicular to its opposite edge.','Vector orthogonality gives the forward implication, while the converse must show all four altitude lines meet rather than just pairwise perpendicular conditions.',None,['Tetrahedra','Vectors','Orthogonality'],date='1978-03-21')
add(1978,'BMO',5,4.5,'Geometry',r'Inside a cube of side 15 lie 11000 points. Prove that some sphere of radius 1 contains at least six of them.','A carefully chosen subdivision almost saturates the numerical bound; its small cubes must fit strictly inside unit spheres.',r'Divide each cube edge into 13 equal pieces, producing $13^3=2197$ small cubes. Assign boundary points consistently to one cube. Because $11000>5\cdot2197$, some small cube contains at least six points. Its circumradius is $15\sqrt3/26<1$, since $675<676$, so its circumsphere enlarged to radius 1 contains all six.',['Pigeonhole principle','Spatial subdivisions'],date='1978-03-21')
add(1978,'BMO',6,6,'Number theory',r'Show that for positive integers $n$, $2\cos(n\theta)$ is a polynomial of degree $n$ in $2\cos\theta$. Deduce that if $k$ is rational, then $\cos(k\pi)$ is either $0,\pm1/2,\pm1$ or irrational.','The cosine recurrence gives monic integer polynomials; combining periodic angles with the rational-root theorem gives the classification.',r'Put $P_0(X)=2,P_1(X)=X$ and $P_{n+1}(X)=XP_n(X)-P_{n-1}(X)$. The angle-addition identity gives $P_n(2\cos\theta)=2\cos(n\theta)$, and $P_n$ is monic of degree $n$ with integer coefficients for $n\ge1$. If $k=a/b$, then $t=2\cos(k\pi)$ satisfies $P_{2b}(t)-2=0$. If $t$ is rational, the rational-root theorem makes it an integer. Since $|t|\le2$, the five stated cosine values are the only rational possibilities.',['Chebyshev polynomials','Rational-root theorem','Trigonometry'],'The scan says non-zero integer n but degree n requires n>0; negative n gives the same cosine as |n|. This harmless convention is made explicit.',date='1978-03-21')
add(1979,'BMO',1,5,'Geometry',r'Find all triangles with $AB+AC=2$ and $AD+BC=\sqrt5$, where $D$ is the perpendicular foot from $A$ to line $BC$.','The two constraints force equality in a geometric triangle inequality and a weighted Cauchy inequality.',None,['Equality cases','Triangle inequalities','Cauchy-Schwarz'],date='1979-03-14')
add(1979,'BMO',2,6,'Geometry',r'Three rays from $O$ make pairwise angles $\alpha=\angle BOC,\beta=\angle COA,\gamma=\angle AOB$, all between $0$ and $\pi$. For $s>0$, prove there are unique points $X,Y,Z$ on rays $OA,OB,OC$ such that triangles $YOZ,ZOX,XOY$ all have perimeter $2s$. Express $OX$ using $s$ and the three half-angle sines.','Squaring each perimeter equation gives pairwise products in transformed radial variables; positivity is needed for uniqueness and existence.',None,['Cosine rule','Systems of equations','Half-angle identities'],date='1979-03-14')
add(1979,'BMO',3,6.5,'Number theory',r'Distinct positive odd integers $a_1,\ldots,a_n$ have all $\binom n2$ absolute pairwise differences distinct. Prove $\sum_{i=1}^n a_i\ge n(n^2+2)/3$.','The distinct-difference hypothesis must be converted into a strong bound on the sum, not merely on the largest element.',None,['Distinct differences','Extremal sets','Double counting'],date='1979-03-14')
add(1979,'BMO',4,6,'Algebra',r'A function $f:\mathbb Q\to\mathbb Q$ satisfies $f(x+f(y))=f(x)f(y)$ for all rational $x,y$. Prove that $f$ is constant.','The functional equation first gives a period; rationality then turns repeated shifts into strong restrictions on every value.',r'Writing $c=f(0)$, the substitution $y=0$ gives $f(x+c)=cf(x)$. If $c=0$, this forces $f\equiv0$. Otherwise $x=0$ gives $f(f(y))=cf(y)$; taking $y=0$ yields $f(c)=c^2$, while the original equation with $x=0$ is consistent. To force $c=1$, note $f(x+f(0))=cf(x)$ and evaluate $f(f(x)+f(0))$ in two ways: it is $c^2f(x)$ by shifting, and using the original equation at $x=f(0),y=x$ it is $f(0)f(x)=cf(x)$ after $f(c)=c^2$; this needs an additional reduction, so a complete verified proof is not supplied here.',['Functional equations','Rational numbers','Periodicity'],date='1979-03-14')
add(1979,'BMO',5,4.5,'Combinatorics',r'Let $p(n)$ count partitions of $n$ into positive integers. Prove $p(n+1)-2p(n)+p(n-1)\ge0$ for every $n>1$.','Successive partition differences have a natural interpretation, after which an injective map proves their monotonicity.',r'The difference $p(n)-p(n-1)$ counts partitions of $n$ with no part equal to 1: remove one 1 to biject the other partitions with partitions of $n-1$. Map a no-1 partition of $n$ to one of $n+1$ by increasing one largest part by 1. The resulting largest part is unique, so subtracting 1 recovers the original partition. Thus the map is injective, proving $p(n+1)-p(n)\ge p(n)-p(n-1)$.',['Partitions','Injections'],date='1979-03-14')
add(1979,'BMO',6,4.5,'Number theory',r'Prove none of $10001,100010001,1000100010001,\ldots$ is prime, where each term is formed by appending 0001.','Even and odd numbers of blocks require different factorisations; the denominator factors in the odd case must be allocated correctly.',r'With $k\ge2$ blocks, the number is $(100^{2k}-1)/(10000-1)$. If $k$ is even, it is divisible by $10001$; for $k=2$, $10001=73\cdot137$, and later terms are larger. If $k$ is odd, it factors as $\frac{100^k-1}{99}\cdot\frac{100^k+1}{101}$. Both factors are integers (use $100\equiv1\pmod{99}$ and $100\equiv-1\pmod{101}$) and both exceed 1.',['Geometric series','Factorisation'],date='1979-03-14')
add(1980,'BMO',1,4,'Number theory',r'Prove $x^n+y^n=z^n$ has no integer solutions with $n>1$ and $0<x,y\le n$.','Bounding the next nth power above the larger summand avoids any use of Fermat’s last theorem.',r'Assume $x\le y$. Then $z>y$, but the binomial theorem gives $(y+1)^n>y^n+ny^{n-1}\ge2y^n\ge x^n+y^n$, since $y\le n$. Thus $z^n$ lies strictly between $y^n$ and $(y+1)^n$, impossible for an integer $z$.',['Between powers','Binomial theorem'],date='1980-03-13')
add(1980,'BMO',2,4.5,'Algebra',r'Find seven consecutive positive integers $S$ and a degree-five polynomial $P$ with integer coefficients such that $P(n)=n$ for five members of $S$, including both endpoints, and $P(n)=0$ for another member.','Factoring P(x)-x at five chosen integer roots reduces the construction to arranging one small product of gaps.',r'Take $S=\{44,45,46,47,48,49,50\}$ and $P(x)=x+(x-44)(x-45)(x-46)(x-47)(x-50)$. This has degree five and integer coefficients. At $44,45,46,47,50$ the product vanishes, so $P(n)=n$. At $48$, the product is $4\cdot3\cdot2\cdot1\cdot(-2)=-48$, hence $P(48)=0$.',['Polynomial construction','Integer coefficients'],date='1980-03-13')
add(1980,'BMO',3,5.5,'Geometry',r'A square $PQRS$ is inscribed in a semicircle with $P,Q$ on its diameter $AB$ and $R,S$ on its arc. Choose $C$ on the arc so that triangles $ABC$ and square $PQRS$ have equal area. Prove that some line joining one of $A,B$ to one of $R,S$ meets a square side at the incentre of $ABC$.','Equal areas determine the height of C; the resulting right triangle and square then require an exact incentre-coordinate or angle-bisector calculation.',None,['Incentre','Semicircles','Area'],date='1980-03-13')
add(1980,'BMO',4,4,'Algebra',r'For which real $a_0$ is the sequence $a_{n+1}=2^n-3a_n$ strictly increasing for every $n\ge0$?','The homogeneous recurrence component alternates and grows faster than the forcing term, so any nonzero coefficient eventually breaks monotonicity.',r'The general term is $a_n=2^n/5+C(-3)^n$, with $C=a_0-1/5$. Therefore $a_{n+1}-a_n=2^n/5-4C(-3)^n$. If $C\ne0$, one parity of $n$ makes the second term negative and eventually dominant, contradicting strict increase. If $C=0$, the differences are all positive. Thus exactly $a_0=1/5$ works.',['Linear recurrences','Growth rates'],date='1980-03-13')
add(1980,'BMO',5,5.5,'Combinatorics',r'At a party of ten people, no three are mutually acquainted. Prove that four people are pairwise unacquainted.','A degree split reduces the problem to the six-person Ramsey lemma, which must be proved or justified.',r'If someone knows at least four people, any four of those acquaintances are mutually unacquainted, since a known pair would form a triangle with that person. Otherwise choose a person $v$; at least six others do not know $v$. Among any six people there are either three mutual acquaintances or three mutual strangers: from one person, three of the other five have the same relation to them, and inspecting those three proves the assertion. The acquaintance alternative is forbidden here, so three mutual strangers among the six, together with $v$, give the required four.',['Ramsey theory','Graph degrees'],date='1980-03-13')
